"""Large generated stress program (600+ lines)."""
import math


def block_0(n: int, data):
    base = 0 + 3 * 2
    alias = base
    total = 0
    for j in range(n):
        total += base * alias + j * 4
    p = n * base
    q = n * base + 0
    seen = [1, 2, 3, 0]
    hits = 0
    for d in data:
        if d in seen:
            hits += 1
    unused = base * 7
    if False:
        print("dead")
    if total > 100000:
        return total
    return total + p + q + hits


def helper_0(x):
    return x * x + 0


def fact_0(n):
    return 1 if n <= 1 else n * fact_0(n - 1)


